() => {
  // Find all module rows
  const moduleRows = document.querySelectorAll('[data-testid="course-content-item"] button, button[aria-controls*="module"]');
  const results = [];
  // Try alternative: find by specific selectors
  const moduleButtons = document.querySelectorAll('button[id^="module-accordion-"]');
  if (moduleButtons.length > 0) {
    moduleButtons.forEach((btn, i) => {
      const titleEl = btn.querySelector('h3');
      const title = titleEl ? titleEl.textContent.trim() : '';
      results.push({index: i, title: title, html: btn.innerText.substring(0, 200)});
    });
    return results;
  }
  // Try other selectors
  const allButtons = document.querySelectorAll('button');
  const moduleCandidates = [];
  allButtons.forEach((btn, i) => {
    const txt = btn.innerText;
    if (txt.match(/第\s*\d+\s*单元/) && txt.match(/小时/)) {
      moduleCandidates.push({index: i, text: txt.substring(0, 300)});
    }
  });
  return {foundButtons: moduleCandidates.length, candidates: moduleCandidates};
}

() => {
  // Look for all spans that contain text that looks like hours
  const allElements = document.querySelectorAll('span, div');
  const hourInfo = [];
  allElements.forEach(el => {
    const txt = el.innerText || el.textContent;
    if (txt && (txt.match(/^\d+\s*小时/) || txt.match(/^\d+-\d+\s*小时/))) {
      // Only capture short ones
      if (txt.length < 100) {
        hourInfo.push(txt.trim());
      }
    }
  });
  return hourInfo.slice(0, 50);
}

() => {
  // Try to find module buttons and extract their text content
  const buttons = document.querySelectorAll('button');
  const moduleInfo = [];
  buttons.forEach(btn => {
    const txt = btn.innerText || btn.textContent;
    if (txt && /第\s*\d+\s*单元/.test(txt)) {
      moduleInfo.push({
        text: txt,
        // Try to find span children
        childrenText: Array.from(btn.children).map(c => c.textContent.trim()).filter(t => t).join(' | '),
        innerHTML: btn.innerHTML.substring(0, 500)
      });
    }
  });
  return {count: moduleInfo.length, modules: moduleInfo};
}

() => {
  const buttons = document.querySelectorAll('button[id^="module-accordion"]');
  if (buttons.length === 0) {
    // Try finding by other means
    const allBtns = document.querySelectorAll('button');
    const modBtns = [];
    allBtns.forEach(b => {
      if (b.innerText && /第\s*\d+\s*单元/.test(b.innerText)) {
        modBtns.push(b);
      }
    });
    return modBtns.map(b => ({text: b.innerText, html: b.innerHTML.substring(0, 1000)}));
  }
  return buttons.length;
}

() => {
  // Find module accordion buttons
  const buttons = document.querySelectorAll('button[data-testid^="course-content-item"]');
  const result = [];
  buttons.forEach((b, i) => {
    result.push({
      idx: i,
      text: b.innerText,
      // Get the actual text from each span/div child
      children: Array.from(b.querySelectorAll('*')).map(el => el.textContent.trim()).filter(t => t).slice(0, 20)
    });
  });
  return result;
}

() => {
  const meta = document.querySelector('meta[name="description"]');
  const ogDesc = document.querySelector('meta[property="og:description"]');
  const title = document.querySelector('meta[property="og:title"]');
  // Also get all module buttons and their parent text
  const buttons = document.querySelectorAll('button[id^="module-accordion"]');
  const modules = [];
  buttons.forEach(b => {
    modules.push(b.innerText.replace(/\n+/g, ' | '));
  });
  return {
    description: meta ? meta.content : null,
    ogDesc: ogDesc ? ogDesc.content : null,
    title: title ? title.content : null,
    modules: modules
  };
}
